"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import type { ReservationView } from "@/lib/present";
import { api } from "./api";
import { SlotPicker, type PickedSlot } from "./SlotPicker";
import { Button, Card, Field, inputClass, Notice } from "./ui";

type Props = { businessId: string; slug: string; reservation: ReservationView; today: string; canManage: boolean; canErase: boolean; ticketUrl: string | null };
type Verify = { result: string; message: string; checkedIn: boolean };

export function ReservationActions({ businessId, slug, reservation: r, today, canManage, canErase, ticketUrl }: Props) {
  const router = useRouter();
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [info, setInfo] = useState("");
  const [panel, setPanel] = useState<"none" | "move" | "cancel" | "override" | "erase">("none");
  const [date, setDate] = useState(r.date < today ? today : r.date);
  const [party, setParty] = useState(r.partySize);
  const [slot, setSlot] = useState<PickedSlot | null>(null);
  const [notes, setNotes] = useState(r.notes);
  const [overrideMsg, setOverrideMsg] = useState("");
  const base = `/api/b/${businessId}`;
  const open = r.status === "pending" || r.status === "confirmed";

  async function run(fn: () => Promise<unknown>, ok: string) {
    setBusy(true); setError(""); setInfo("");
    try { await fn(); setInfo(ok); setPanel("none"); router.refresh(); }
    catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  }
  const patch = (body: Record<string, unknown>, ok: string) => run(() => api(`${base}/reservations/${r.id}`, { method: "PATCH", body }), ok);

  async function checkIn(override = false) {
    setBusy(true); setError(""); setInfo("");
    try {
      const v = await api<Verify>(`${base}/checkin`, { body: { reservationId: r.id, commit: true, override } });
      if (v.checkedIn) { setInfo(`${r.customerName} is checked in.`); setPanel("none"); }
      else if (v.result === "too_early" || v.result === "expired") { setOverrideMsg(v.message); setPanel("override"); }
      else setError(v.message);
      router.refresh();
    } catch (e) { setError((e as Error).message); }
    finally { setBusy(false); }
  }

  return (
    <Card className="space-y-4 p-5">
      <h2 className="text-lg font-bold">Actions</h2>
      {info && <Notice tone="ok">{info}</Notice>}
      {error && <Notice tone="error">{error}</Notice>}

      <div className="flex flex-wrap gap-2">
        {r.status === "confirmed" && <Button variant="mint" disabled={busy} onClick={() => checkIn(false)} data-testid="checkin-button">Check in</Button>}
        {r.status === "pending" && canManage && <Button disabled={busy} onClick={() => patch({ action: "confirm" }, "Reservation confirmed.")}>Confirm reservation</Button>}
        {open && canManage && <Button variant="quiet" disabled={busy} onClick={() => setPanel(panel === "move" ? "none" : "move")}>Change time or party</Button>}
        {r.status === "confirmed" && canManage && <Button variant="quiet" disabled={busy} onClick={() => patch({ action: "no_show" }, "Marked as no-show.")}>Mark no-show</Button>}
        {r.status === "checked_in" && canManage && <Button variant="quiet" disabled={busy} onClick={() => patch({ action: "complete" }, "Marked as completed.")}>Mark completed</Button>}
        {open && canManage && <Button variant="danger" disabled={busy} onClick={() => setPanel(panel === "cancel" ? "none" : "cancel")}>Cancel reservation</Button>}
        {ticketUrl && <a href={ticketUrl} target="_blank" rel="noreferrer" className="inline-flex min-h-11 items-center rounded-xl px-4 text-[15px] font-semibold ring-1 ring-line hover:bg-paper">Open ticket</a>}
      </div>
      {open && !canManage && <p className="text-[15px] text-muted">Changing or cancelling a reservation needs a manager.</p>}

      {panel === "override" && (
        <div className="space-y-3 rounded-xl bg-amber-soft p-4">
          <p className="font-semibold text-amber">{overrideMsg}</p>
          <p className="text-[15px] text-ink-soft">You can still let the guest in. The exception is recorded with your name.</p>
          <div className="flex gap-2">
            <Button variant="quiet" disabled={busy} onClick={() => setPanel("none")}>Not now</Button>
            <Button variant="mint" disabled={busy} onClick={() => checkIn(true)}>Check in anyway</Button>
          </div>
        </div>
      )}

      {panel === "cancel" && (
        <div className="space-y-3 rounded-xl bg-rose-soft p-4">
          <p className="font-semibold">Cancel {r.customerName}&apos;s reservation?</p>
          <p className="text-[15px] text-ink-soft">The ticket stops working immediately and the customer is emailed if they left an address.</p>
          <div className="flex gap-2">
            <Button variant="quiet" disabled={busy} onClick={() => setPanel("none")}>Keep it</Button>
            <Button variant="danger" disabled={busy} onClick={() => patch({ action: "cancel" }, "Reservation cancelled.")}>Yes, cancel it</Button>
          </div>
        </div>
      )}

      {panel === "move" && (
        <div className="space-y-3 rounded-xl bg-paper p-4">
          <div className="grid grid-cols-2 gap-3">
            <Field label="Date"><input type="date" className={inputClass} value={date} onChange={(e) => { setDate(e.target.value); setSlot(null); }} /></Field>
            <Field label="Party size"><input type="number" min={1} className={inputClass} value={party} onChange={(e) => { setParty(Math.max(1, Number(e.target.value) || 1)); setSlot(null); }} /></Field>
          </div>
          <SlotPicker endpoint={`${base}/availability?exclude=${r.id}`} date={date} party={party} selected={slot?.start ?? null} onPick={setSlot} />
          <Button disabled={busy || !slot} onClick={() => patch({ action: "reschedule", startsAt: slot!.start, partySize: party }, "Reservation updated.")}>{slot ? `Move to ${slot.time}` : "Choose a time"}</Button>
        </div>
      )}

      <form className="flex items-end gap-2" onSubmit={(e) => { e.preventDefault(); void patch({ action: "notes", notes }, "Note saved."); }}>
        <Field label="Staff note" className="flex-1"><input className={inputClass} maxLength={500} value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="Allergies, occasion, seating preference" /></Field>
        <Button variant="quiet" disabled={busy || notes === r.notes || !open}>Save note</Button>
      </form>

      {canErase && !open && (
        <div className="border-t border-line pt-3">
          {panel === "erase" ? (
            <div className="space-y-3 rounded-xl bg-rose-soft p-4">
              <p className="font-semibold">Delete this customer&apos;s personal data?</p>
              <p className="text-[15px] text-ink-soft">Their name, email, phone and notes are removed from all their reservations here. The bookings stay for your records. This cannot be undone.</p>
              <div className="flex gap-2">
                <Button variant="quiet" disabled={busy} onClick={() => setPanel("none")}>Keep</Button>
                <Button variant="danger" disabled={busy} onClick={() => run(async () => { await api(`${base}/customers/${r.customerId}`, { method: "DELETE" }); router.push(`/app/${slug}/reservations`); }, "Customer data deleted.")}>Delete personal data</Button>
              </div>
            </div>
          ) : <button type="button" className="text-[15px] font-semibold text-rose" onClick={() => setPanel("erase")}>Delete customer&apos;s personal data</button>}
        </div>
      )}
    </Card>
  );
}
