"use client";
import { useEffect, useState } from "react";
import { api } from "./api";
import { cx } from "./ui";

export type PickedSlot = { start: string; time: string };
type Day = { open: boolean; closedReason: string | null; slots: { start: string; time: string; available: boolean }[] };

/** Times for one day from the availability API. Only free times can be chosen. */
export function SlotPicker({ endpoint, date, party, selected, onPick }: { endpoint: string; date: string; party: number; selected: string | null; onPick: (s: PickedSlot | null) => void }) {
  const [day, setDay] = useState<Day | null>(null);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!date || !party) return;
    let live = true;
    setDay(null); setError("");
    api<Day>(`${endpoint}${endpoint.includes("?") ? "&" : "?"}date=${date}&party=${party}`)
      .then((d) => { if (live) setDay(d); })
      .catch((e) => { if (live) setError((e as Error).message); });
    return () => { live = false; };
  }, [endpoint, date, party]);

  if (error) return <p role="alert" className="text-rose">{error}</p>;
  if (!day) return <p className="text-muted" aria-busy="true">Checking availability…</p>;
  if (!day.open) return <p className="rounded-xl bg-paper px-4 py-3 text-ink-soft">{day.closedReason ?? "Closed on this day."} Try another date.</p>;
  const free = day.slots.filter((s) => s.available);
  if (free.length === 0) return <p className="rounded-xl bg-paper px-4 py-3 text-ink-soft">Nothing is free on this day for {party} {party === 1 ? "guest" : "guests"}. Try another date.</p>;
  return (
    <div role="radiogroup" aria-label="Available times" className="grid grid-cols-4 gap-2 sm:grid-cols-5">
      {day.slots.map((s) => (
        <button
          key={s.start} type="button" role="radio" aria-checked={selected === s.start} disabled={!s.available}
          onClick={() => onPick(selected === s.start ? null : { start: s.start, time: s.time })}
          className={cx(
            "min-h-11 rounded-xl text-[15px] font-semibold tabular transition-colors",
            !s.available && "cursor-not-allowed bg-paper text-muted/50 line-through",
            s.available && selected !== s.start && "bg-white ring-1 ring-line hover:ring-brand",
            selected === s.start && "bg-brand text-white",
          )}
        >{s.time}</button>
      ))}
    </div>
  );
}
